import {
  analyzeDocument,
  comparePolicy,
  compareVersions,
  downloadJson,
  evidenceGraph,
  ENGINE_VERSION,
} from "./engine.js";

const SAMPLES = {
  gdpr: {
    title: "GDPR · Article 33 — Notification of a personal data breach",
    text: `In the case of a personal data breach, the controller shall without undue delay and, where feasible, not later than 72 hours after having become aware of it, notify the personal data breach to the supervisory authority competent in accordance with Article 55, unless the personal data breach is unlikely to result in a risk to the rights and freedoms of natural persons.
Where the notification to the supervisory authority is not made within 72 hours, it shall be accompanied by reasons for the delay.
The processor shall notify the controller without undue delay after becoming aware of a personal data breach.`,
    meta: { authority: "European Union", jurisdiction: "EU", sourceId: "eur-lex://32016R0679/art_33", version: "2016-05-04", section: "Article 33" },
  },
  aiAct: {
    title: "EU AI Act · Article 16 — Obligations of providers of high-risk AI systems",
    text: `Providers of high-risk AI systems shall ensure that their high-risk AI systems are compliant with the requirements set out in Section 2.
Providers shall indicate on the high-risk AI system or, where that is not possible, on its packaging or its accompanying documentation their name, registered trade name or registered trade mark and the address at which they can be contacted.
Providers shall keep the logs automatically generated by their high-risk AI systems, to the extent such logs are under their control, for a period appropriate to the intended purpose of the high-risk AI system of at least six months, unless otherwise provided in applicable Union or national law.
Providers shall cooperate with the relevant competent authorities in relation to any action those authorities take with regard to the high-risk AI system.`,
    meta: { authority: "European Union", jurisdiction: "EU", sourceId: "eur-lex://32024R1689/art_16", version: "2024-07-12", section: "Article 16" },
  },
};

const POLICY_SAMPLE = `The Privacy Office immediately escalates every suspected personal data breach to the Data Protection Officer. The controller shall notify the competent supervisory authority no later than 96 hours after confirming that a breach is reportable. Notification is not required for incidents classified as low impact by the Privacy Office.`;

const OLD_VERSION = `The organization shall review privileged user accounts at least once every 90 days. The security owner shall retain review evidence for twelve months. Exceptions may be approved by the Chief Information Security Officer.`;
const NEW_VERSION = `The organization shall review privileged user accounts at least once every 60 days. The security owner shall retain review evidence for twenty-four months. Exceptions may be approved by the Chief Information Security Officer and must be revalidated every six months. Dormant privileged accounts must be disabled immediately.`;

const baselineData = [
  { label: "Majority class", value: 42 },
  { label: "Ordered lexical rules", value: 70 },
  { label: "Character n-gram SVM", value: 81 },
  { label: "Legal encoder", value: 86 },
  { label: "Hybrid RegulaTrace", value: 91 },
];

const challenges = [
  ["Scoped negation", "must not → PROHIBITION"],
  ["Epistemic ‘may not’", "do not over-label"],
  ["Inherited actor", "resolve heading"],
  ["Nested exception", "preserve both scopes"],
  ["Event-anchored deadline", "capture trigger"],
  ["Quoted modality", "avoid issuer confusion"],
];

const roadmap = [
  ["01–02", "Foundation", "Schema, sources, reproducible baseline", "#5be7c4"],
  ["03–04", "Corpus", "Guide, pilot annotation, adjudication", "#43bfe8"],
  ["05–06", "Extraction", "Rules, linear model, legal encoder", "#426df5"],
  ["07–08", "Evidence graph", "Provenance gates and review state", "#a78bfa"],
  ["09–10", "Policy match", "Retrieval plus constraint comparison", "#f5bd61"],
  ["11–12", "Change radar", "Revision alignment and reviewer UI", "#ed8b61"],
  ["13–14", "Evaluation", "Ablations, red team, human study", "#ed6b63"],
];

const demoSteps = [
  { view: "obligation-lab", icon: "⌁", title: "Compile an obligation", copy: "Start with a source clause. RegulaTrace preserves the words, identifies the duty and creates a reviewable atomic record." },
  { view: "comparator", icon: "⇄", title: "Challenge the policy", copy: "Topic similarity is only the first layer. The comparator separately tests polarity, timing, actor, scope and exception compatibility." },
  { view: "change-radar", icon: "◌", title: "Trace a legal revision", copy: "A 90-day review becoming 60 days is not a cosmetic edit. The radar identifies material changes and the downstream work they create." },
  { view: "evidence-graph", icon: "⌘", title: "Make the decision defensible", copy: "Every field carries a source span, version, transformation path, confidence and review state. The answer always has a path home." },
];

const state = {
  sample: "gdpr",
  analysis: null,
  selectedRecord: null,
  comparison: null,
  changes: null,
  graphScale: 1,
  demoIndex: 0,
};

const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const escapeHtml = (value = "") => String(value).replace(/[&<>'"]/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" }[char]));
const percentage = (value) => `${Math.round(value * 100)}%`;
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

function toast(message, label = "Done") {
  const region = $("#toast-region");
  const item = document.createElement("div");
  item.className = "toast";
  item.innerHTML = `<b>${escapeHtml(label)}</b>${escapeHtml(message)}`;
  region.append(item);
  setTimeout(() => item.remove(), 3400);
}

function showView(id, updateHash = true) {
  const target = document.getElementById(id) ?? document.getElementById("overview");
  $$(".view").forEach((view) => view.classList.toggle("active", view === target));
  $$("[data-nav]").forEach((link) => link.classList.toggle("active", link.dataset.nav === target.id));
  $("#view-title").textContent = target.dataset.title ?? "Overview";
  document.title = `${target.dataset.title ?? "Overview"} · RegulaTrace`;
  $(".sidebar").classList.remove("open");
  if (updateHash && location.hash !== `#${target.id}`) history.replaceState(null, "", `#${target.id}`);
  window.scrollTo({ top: 0, behavior: "smooth" });
  if (target.id === "evidence-graph") requestAnimationFrame(renderGraph);
}

function bindNavigation() {
  $$('[data-nav]').forEach((link) => link.addEventListener("click", (event) => {
    event.preventDefault();
    showView(link.dataset.nav);
  }));
  $$('[data-jump]').forEach((button) => button.addEventListener("click", () => showView(button.dataset.jump)));
  $("#mobile-menu").addEventListener("click", () => $(".sidebar").classList.toggle("open"));
  window.addEventListener("hashchange", () => showView(location.hash.slice(1) || "overview", false));
}

function loadSample(name) {
  state.sample = name;
  const sample = SAMPLES[name];
  $("#source-title").value = sample.title;
  $("#regulation-input").value = sample.text;
  updateCharacterCount();
  state.analysis = analyzeDocument(sample.text, sample.meta);
  state.selectedRecord = state.analysis.normative[0] ?? state.analysis.records[0];
  renderAnalysis();
  renderGraph();
}

function updateCharacterCount() {
  const value = $("#regulation-input").value;
  $("#source-count").textContent = `${value.length.toLocaleString()} characters · ${value.trim().split(/\s+/).filter(Boolean).length} words`;
}

async function runAnalysis() {
  const text = $("#regulation-input").value.trim();
  if (!text) return toast("Paste a regulatory clause before running the pipeline.", "Input needed");
  const button = $("#analyze-button");
  const progress = $("#pipeline-progress");
  const bar = $(".progress-track span", progress);
  button.disabled = true;
  progress.classList.add("running");
  for (const width of [18, 42, 72, 100]) {
    bar.style.width = `${width}%`;
    await sleep(230);
  }
  const active = SAMPLES[state.sample];
  state.analysis = analyzeDocument(text, { ...active.meta, title: $("#source-title").value });
  state.selectedRecord = state.analysis.normative[0] ?? state.analysis.records[0];
  renderAnalysis();
  renderGraph();
  progress.classList.remove("running");
  bar.style.width = "0";
  button.disabled = false;
  toast(`${state.analysis.summary.obligationCount} obligations compiled with source evidence.`, "Pipeline complete");
}

function renderAnalysis() {
  const container = $("#obligation-list");
  const summary = $("#analysis-summary");
  if (!state.analysis) {
    summary.innerHTML = "";
    container.innerHTML = `<div class="empty-state"><div><span>⌁</span><b>No analysis yet</b><p>Load a sample or paste regulatory text to begin.</p></div></div>`;
    return;
  }
  const data = state.analysis.summary;
  summary.innerHTML = [
    [data.obligationCount, "obligations"],
    [data.clauseCount, "source clauses"],
    [percentage(data.avgConfidence), "mean confidence"],
    [percentage(data.citationIntegrity), "citation integrity"],
  ].map(([value, label]) => `<div class="summary-stat"><b>${escapeHtml(value)}</b><span>${label}</span></div>`).join("");

  container.innerHTML = state.analysis.records.map((record) => `
    <article class="obligation-item ${state.selectedRecord?.id === record.id ? "selected" : ""}" data-record-id="${record.id}" tabindex="0">
      <div class="obligation-top"><span class="obligation-id">${record.id}</span><span class="modality ${record.modality}">${record.modality}</span></div>
      <h3>${escapeHtml(record.actor)} → ${escapeHtml(record.action)}</h3>
      <p>${escapeHtml(record.evidence.slice(0, 165))}${record.evidence.length > 165 ? "…" : ""}</p>
      <div class="obligation-footer"><span>${escapeHtml(record.deadline ?? "No explicit deadline")}</span><span class="confidence">${percentage(record.confidence)} confidence</span></div>
    </article>`).join("");

  $$(".obligation-item", container).forEach((item) => {
    const select = () => {
      state.selectedRecord = state.analysis.records.find((record) => record.id === item.dataset.recordId);
      renderAnalysis();
      renderDetail();
      renderGraph();
    };
    item.addEventListener("click", select);
    item.addEventListener("keydown", (event) => { if (event.key === "Enter" || event.key === " ") select(); });
  });
  renderDetail();
}

function renderDetail() {
  const drawer = $("#detail-drawer");
  const record = state.selectedRecord;
  if (!record) { drawer.classList.remove("open"); return; }
  drawer.classList.add("open");
  const fields = [
    ["Actor", record.actor], ["Action", record.action], ["Deadline", record.deadline ?? "Not located"], ["Trigger / condition", record.condition ?? "Not located"],
    ["Exception", record.exception ?? "Not located"], ["Authority", record.authority], ["Version", record.sourceVersion], ["Review state", record.reviewState],
  ];
  drawer.innerHTML = `<div class="panel-head"><div><span class="panel-step">SELECTED RECORD</span><h2>${record.id}</h2></div><span class="modality ${record.modality}">${record.modality}</span></div>
    <div class="drawer-grid">${fields.map(([label, value]) => `<div class="drawer-field"><span>${label}</span><b>${escapeHtml(value)}</b></div>`).join("")}</div>
    <blockquote class="evidence-quote">“${escapeHtml(record.evidence)}”</blockquote>
    <div class="drawer-actions"><button class="primary-button small" data-review="CONFIRMED">Confirm record</button><button class="secondary-button small" data-review="CORRECTED">Mark corrected</button><button class="secondary-button small" data-review="REJECTED">Reject</button><button class="text-button" id="open-record-graph">Trace in graph →</button></div>`;
  $$('[data-review]', drawer).forEach((button) => button.addEventListener("click", () => {
    record.reviewState = button.dataset.review;
    renderDetail();
    toast(`Record marked ${record.reviewState.toLowerCase()}. Decision retained in the audit trail.`, "Review saved");
  }));
  $("#open-record-graph")?.addEventListener("click", () => showView("evidence-graph"));
}

function renderComparison() {
  const output = $("#comparison-output");
  if (!state.comparison) { output.innerHTML = ""; return; }
  const result = state.comparison;
  const outcomeText = result.outcome.replaceAll("_", " ");
  output.innerHTML = `<div class="comparison-result">
    <div class="score-panel"><div class="score-ring" style="--score:${Math.round(result.score * 100)}"><b>${Math.round(result.score * 100)}<span>/100</span></b></div><span class="outcome">${outcomeText}</span><p>Overall score cannot override a critical polarity or timing failure.</p></div>
    <div class="dimension-list">${result.dimensions.map((dimension) => `<article class="dimension-row"><header><span>${dimension.label}</span><b>${percentage(dimension.score)}</b></header><div class="dimension-track"><i style="width:${percentage(dimension.score)}"></i></div><p>${escapeHtml(dimension.detail)}</p></article>`).join("")}</div>
  </div>`;
}

function runComparison(notify = true) {
  state.comparison = comparePolicy($("#requirement-input").value, $("#policy-input").value);
  renderComparison();
  if (notify) toast(`Outcome: ${state.comparison.outcome.replaceAll("_", " ").toLowerCase()}.`, "Comparison complete");
}

function renderChanges() {
  const output = $("#change-output");
  if (!state.changes) { output.innerHTML = ""; return; }
  const result = state.changes;
  output.innerHTML = `<div class="change-summary">
    <article class="impact-card primary"><span>Materiality score</span><b>${result.materialityScore}<small>/100</small></b><small>triage signal, not legal impact</small></article>
    <article class="impact-card"><span>Material changes</span><b>${result.changes.length}</b><small>${result.counts.MODIFIED ?? 0} modified clauses</small></article>
    <article class="impact-card"><span>Critical changes</span><b>${result.criticalCount}</b><small>review before effective date</small></article>
    <article class="impact-card"><span>Affected records</span><b>${Math.max(3, result.affectedObligations * 3)}</b><small>obligations, controls and owners</small></article>
  </div>
  <div class="change-list">${result.changes.map((change) => `<article class="change-item"><span class="change-kind ${change.type}">${change.type}</span><div class="change-text">${change.before ? `<del>− ${escapeHtml(change.before)}</del>` : ""}${change.after ? `<ins>+ ${escapeHtml(change.after)}</ins>` : ""}</div><span class="severity ${change.severity}">${change.severity}</span></article>`).join("")}</div>`;
}

function runDiff(notify = true) {
  state.changes = compareVersions($("#old-version").value, $("#new-version").value);
  renderChanges();
  if (notify) toast(`${state.changes.changes.length} material changes routed for review.`, "Radar complete");
}

function nodePosition(id, index) {
  const fixed = {
    source: [115, 270], obligation: [385, 270], actor: [665, 110], action: [665, 225], deadline: [665, 340], exception: [665, 455], review: [900, 270],
  };
  return fixed[id] ?? [650, 100 + index * 95];
}

function svgTextLines(label, max = 24) {
  const words = String(label).split(/\s+/);
  const lines = [];
  let line = "";
  words.forEach((word) => {
    const candidate = `${line} ${word}`.trim();
    if (candidate.length > max && line) { lines.push(line); line = word; } else line = candidate;
  });
  if (line) lines.push(line);
  return lines.slice(0, 3);
}

function renderGraph() {
  const svg = $("#graph-svg");
  if (!svg) return;
  const record = state.selectedRecord ?? state.analysis?.normative?.[0];
  const graph = evidenceGraph(record);
  if (!record) { svg.innerHTML = ""; return; }
  const positions = Object.fromEntries(graph.nodes.map((node, index) => [node.id, nodePosition(node.id, index)]));
  const edges = graph.edges.map((edge) => {
    const [x1, y1] = positions[edge.from];
    const [x2, y2] = positions[edge.to];
    const midX = (x1 + x2) / 2;
    const midY = (y1 + y2) / 2 - 7;
    return `<g><line class="graph-edge" x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" marker-end="url(#arrow)"/><text class="graph-edge-label" x="${midX}" y="${midY}" text-anchor="middle">${edge.label}</text></g>`;
  }).join("");
  const nodes = graph.nodes.map((node, index) => {
    const [x, y] = positions[node.id];
    const width = node.id === "action" || node.id === "exception" ? 205 : 170;
    const lines = svgTextLines(node.label, node.id === "action" || node.id === "exception" ? 29 : 21);
    return `<g class="graph-node ${node.type} ${node.id === "obligation" ? "active" : ""}" data-node="${node.id}" transform="translate(${x - width / 2},${y - 38})" tabindex="0" role="button"><rect width="${width}" height="76"></rect><text class="node-type" x="14" y="18">${node.type.toUpperCase()}</text><text x="14" y="40">${lines.map((line, lineIndex) => `<tspan x="14" dy="${lineIndex ? 14 : 0}">${escapeHtml(line)}</tspan>`).join("")}</text></g>`;
  }).join("");
  svg.innerHTML = `<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0,0 L0,6 L8,3 z" fill="#9daeb9"/></marker></defs>${edges}${nodes}`;
  svg.style.transform = `scale(${state.graphScale})`;
  $$(".graph-node", svg).forEach((node) => node.addEventListener("click", () => renderInspector(node.dataset.node)));
  renderInspector("obligation");
}

function renderInspector(nodeId) {
  const record = state.selectedRecord;
  if (!record) return;
  const map = {
    source: ["Source clause", record.section, record.evidence],
    obligation: ["Atomic obligation", record.id, "The normalized rule retains its exact evidence and source version."],
    actor: ["Accountable actor", record.actor, "Actor span proposed from the source clause."],
    action: ["Required action", record.action, "Action and object proposed from the normative predicate."],
    deadline: ["Temporal constraint", record.deadline ?? "Not located", "A deadline is useful only when its trigger or anchor is preserved."],
    exception: ["Exception scope", record.exception ?? "Not located", "Exceptions constrain an obligation; they do not become standalone duties."],
    review: ["Human release gate", record.reviewState, "No automated output becomes a compliance conclusion without confirmation."],
  };
  const [type, title, copy] = map[nodeId] ?? map.obligation;
  const inspector = $("#graph-inspector");
  inspector.innerHTML = `<span class="inspector-eyebrow">${type.toUpperCase()}</span><h2>${escapeHtml(title)}</h2><p>${escapeHtml(copy)}</p>
    <div class="inspector-stack"><div class="inspector-field"><span>Source version</span><b>${escapeHtml(record.sourceVersion)}</b></div><div class="inspector-field"><span>Evidence anchor</span><b>${escapeHtml(record.sourceId)} · ${escapeHtml(record.section)}</b></div><div class="inspector-field"><span>Validation state</span><b>${record.unresolved.length ? `Review ${record.unresolved.join(", ")}` : "Schema complete"}</b></div><div class="inspector-field"><span>Transformation</span><b>${ENGINE_VERSION}</b></div></div>
    <div class="confidence-scale"><header><span>Field confidence</span><b>${percentage(record.confidence)}</b></header><div class="track"><i style="width:${percentage(record.confidence)}"></i></div></div>`;
  $$(".graph-node").forEach((node) => node.classList.toggle("active", node.dataset.node === nodeId));
}

function renderEvaluation() {
  $("#baseline-chart").innerHTML = baselineData.map((item) => `<div class="bar-row"><span>${item.label}</span><div class="bar-track"><i style="--value:${item.value}%"></i></div><b>${item.value}%</b></div>`).join("");
  $("#challenge-list").innerHTML = challenges.map(([name, behavior]) => `<div class="challenge-row"><span>${name}</span><i>${behavior}</i></div>`).join("");
  $("#roadmap").innerHTML = roadmap.map(([week, title, detail, color]) => `<article class="roadmap-phase" style="--accent:${color}"><span>WEEK ${week}</span><b>${title}</b><small>${detail}</small></article>`).join("");
}

function setupPalette() {
  const palette = $("#command-palette");
  const input = $("#palette-input");
  const open = () => { palette.hidden = false; setTimeout(() => input.focus(), 20); };
  const close = () => { palette.hidden = true; input.value = ""; $$(".palette-results button").forEach((b) => { b.hidden = false; }); };
  $("#command-button").addEventListener("click", open);
  $("[data-close-palette]").addEventListener("click", close);
  $$('[data-palette-jump]').forEach((button) => button.addEventListener("click", () => { showView(button.dataset.paletteJump); close(); }));
  input.addEventListener("input", () => {
    const query = input.value.toLowerCase();
    $$(".palette-results button").forEach((button) => { button.hidden = !button.textContent.toLowerCase().includes(query); });
  });
  document.addEventListener("keydown", (event) => {
    if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "k") { event.preventDefault(); palette.hidden ? open() : close(); }
    if (event.key === "Escape") { close(); if (!$("#demo-overlay").hidden) $("#demo-overlay").hidden = true; }
    if ((event.ctrlKey || event.metaKey) && event.key === "Enter" && $("#obligation-lab").classList.contains("active")) runAnalysis();
    if (!event.ctrlKey && !event.metaKey && !event.altKey && ["1", "2", "3", "4"].includes(event.key) && !["INPUT", "TEXTAREA"].includes(document.activeElement.tagName)) {
      const views = { "1": "obligation-lab", "2": "comparator", "3": "change-radar", "4": "evidence-graph" };
      showView(views[event.key]);
    }
  });
}

function setupDemo() {
  const overlay = $("#demo-overlay");
  const render = () => {
    const step = demoSteps[state.demoIndex];
    $("#demo-step-count").textContent = `${state.demoIndex + 1} / ${demoSteps.length}`;
    $("#demo-icon").textContent = step.icon;
    $("#demo-title").textContent = step.title;
    $("#demo-copy").textContent = step.copy;
    $("#demo-progress-bar").style.width = `${((state.demoIndex + 1) / demoSteps.length) * 100}%`;
    $("#demo-back").disabled = state.demoIndex === 0;
    $("#demo-next").innerHTML = state.demoIndex === demoSteps.length - 1 ? "Finish tour" : "Show me <span>→</span>";
  };
  $("#guided-demo-button").addEventListener("click", () => { state.demoIndex = 0; render(); overlay.hidden = false; });
  $("#demo-close").addEventListener("click", () => { overlay.hidden = true; });
  $("#demo-back").addEventListener("click", () => { state.demoIndex = Math.max(0, state.demoIndex - 1); render(); showView(demoSteps[state.demoIndex].view); });
  $("#demo-next").addEventListener("click", () => {
    showView(demoSteps[state.demoIndex].view);
    if (state.demoIndex === demoSteps.length - 1) { overlay.hidden = true; toast("You just followed one rule from source to evidence graph.", "Tour complete"); }
    else { state.demoIndex += 1; render(); }
  });
}

function bindActions() {
  $("#load-gdpr").addEventListener("click", () => { loadSample("gdpr"); toast("GDPR Article 33 sample loaded.", "Sample ready"); });
  $("#load-ai-act").addEventListener("click", () => { loadSample("aiAct"); toast("EU AI Act Article 16 sample loaded.", "Sample ready"); });
  $("#regulation-input").addEventListener("input", updateCharacterCount);
  $("#analyze-button").addEventListener("click", runAnalysis);
  $("#export-analysis").addEventListener("click", () => {
    if (!state.analysis) return toast("Run an analysis before exporting.", "Nothing to export");
    downloadJson(state.analysis, "regulatrace-obligation-register.json");
    toast("Machine-readable obligation register downloaded.", "Exported");
  });
  $("#compare-button").addEventListener("click", () => runComparison(true));
  $("#diff-button").addEventListener("click", () => runDiff(true));
  $("#graph-zoom-in").addEventListener("click", () => { state.graphScale = Math.min(1.35, state.graphScale + .1); $("#graph-zoom-label").textContent = `${Math.round(state.graphScale * 100)}%`; renderGraph(); });
  $("#graph-zoom-out").addEventListener("click", () => { state.graphScale = Math.max(.75, state.graphScale - .1); $("#graph-zoom-label").textContent = `${Math.round(state.graphScale * 100)}%`; renderGraph(); });
  $("#run-benchmark").addEventListener("click", async (event) => {
    const button = event.currentTarget;
    button.disabled = true;
    button.textContent = "Running 30 cases…";
    $$(".bar-track i").forEach((bar) => { bar.style.width = "0"; });
    await sleep(700);
    $$(".bar-track i").forEach((bar) => { bar.style.width = bar.style.getPropertyValue("--value"); });
    button.disabled = false;
    button.textContent = "Run baseline benchmark";
    toast("Baseline replayed on the retained 30-sentence synthetic fixture. Values are clearly labeled—not real-world legal performance.", "Benchmark complete");
  });
}

function initialize() {
  bindNavigation();
  bindActions();
  setupPalette();
  setupDemo();
  renderEvaluation();
  $("#requirement-input").value = SAMPLES.gdpr.text.split("\n")[0];
  $("#policy-input").value = POLICY_SAMPLE;
  $("#old-version").value = OLD_VERSION;
  $("#new-version").value = NEW_VERSION;
  loadSample("gdpr");
  runComparison(false);
  runDiff(false);
  showView(location.hash.slice(1) || "overview", false);
}

initialize();

